  1	/**
  2	 * Meta API Routes
  3	 *
  4	 * REST endpoints for meta operations:
  5	 * - GET /api/meta/session - get session context
  6	 * - GET /api/meta/agents - list agents
  7	 * - PATCH /api/meta/agents/:id - update agent definition
  8	 * - GET /api/meta/workflows - list workflows
  9	 * - GET /api/meta/observations - list observations with filter
 10	 *
 11	 * AC Coverage:
 12	 * - ac-15: GET /api/meta/session returns session context
 13	 * - ac-16: GET /api/meta/agents returns all agents
 14	 * - ac-17: GET /api/meta/workflows returns all workflows
 15	 * - ac-18: GET /api/meta/observations with filter
 16	 * - @ui-agent-dispatch ac-4: PATCH /api/meta/agents/:id updates agent definition
 17	 */
 18	
 19	import { Elysia, t } from 'elysia';
 20	import {
 21	  initContext,
 22	  loadMetaContext,
 23	  loadSessionContext,
 24	  saveMetaItem,
 25	} from '../../parser/index.js';
 26	import { commitIfShadow } from '../../parser/shadow.js';
 27	import type { Agent } from '../../schema/meta.js';
 28	import { AgentDispatchEventSchema } from '../../schema/meta.js';
 29	
 30	interface MetaRouteOptions {}
 31	
 32	export function createMetaRoutes(options: MetaRouteOptions = {}) {
 33	  // No closure-scoped kspecDir needed - comes from middleware
 34	
 35	  return new Elysia({ prefix: '/api/meta' })
 36	    // AC: @api-contract ac-15 - Get session context
 37	    .get('/session', async ({ projectContext }) => {
 38	      // AC: @multi-directory-daemon ac-1, ac-24 - Use project context from middleware
 39	      const ctx = await initContext(projectContext.path);
 40	      const session = await loadSessionContext(ctx);
 41	
 42	      // AC: @api-contract ac-15 - Return session context (focus, threads, questions)
 43	      return {
 44	        focus: session.focus,
 45	        threads: session.threads || [],
 46	        questions: session.questions || [],
 47	        updated_at: session.updated_at,
 48	      };
 49	    })
 50	
 51	    // AC: @api-contract ac-16 - List agents
 52	    .get('/agents', async ({ projectContext }) => {
 53	      // AC: @multi-directory-daemon ac-1, ac-24 - Use project context from middleware
 54	      const ctx = await initContext(projectContext.path);
 55	      const meta = await loadMetaContext(ctx);
 56	
 57	      // AC: @api-contract ac-16 - Return all defined agents
 58	      const agents = meta.agents;
 59	
 60	      return {
 61	        items: agents,
 62	        total: agents.length,
 63	      };
 64	    })
 65	
 66	    // AC: @ui-agent-dispatch ac-4 - Update agent definition
 67	    // Body schema mirrors editable fields from AgentSchema (src/schema/meta.ts).
 68	    // Dispatch event enum values derived from AgentDispatchEventSchema.
 69	    .patch(
 70	      '/agents/:id',
 71	      async ({ params, body, projectContext }) => {
 72	        const ctx = await initContext(projectContext.path);
 73	        const meta = await loadMetaContext(ctx);
 74	
 75	        // Find the agent by id
 76	        const agent = meta.agents.find((a) => a.id === params.id);
 77	        if (!agent) {
 78	          throw new Error(`Agent not found: ${params.id}`);
 79	        }
 80	
 81	        // Apply partial updates from body — result satisfies Agent type from schema
 82	        const updated: Agent = { ...agent, ...body };
 83	
 84	        await saveMetaItem(ctx, updated, 'agent');
 85	        await commitIfShadow(ctx.shadow, `meta: update agent ${params.id}`);
 86	
 87	        return updated;
 88	      },
 89	      {
 90	        params: t.Object({
 91	          id: t.String(),
 92	        }),
 93	        // Editable fields from AgentSchema — dispatch.on enum derived from AgentDispatchEventSchema
 94	        body: t.Object({
 95	          name: t.Optional(t.String()),
 96	          description: t.Optional(t.String()),
 97	          adapter: t.Optional(t.String()),
 98	          dispatch: t.Optional(
 99	            t.Array(
100	              t.Object({
101	                on: t.Union(AgentDispatchEventSchema.options.map((v) => t.Literal(v))),
102	                filter: t.Optional(
103	                  t.Object({
104	                    automation: t.Optional(t.Union([t.Literal('eligible'), t.Literal('ineligible')])),
105	                    tags: t.Optional(t.Array(t.String())),
106	                    priority: t.Optional(t.Number()),
107	                  })
108	                ),
109	              })
110	            )
111	          ),
112	          capabilities: t.Optional(t.Array(t.String())),
113	          tools: t.Optional(t.Array(t.String())),
114	          skills: t.Optional(t.Array(t.String())),
115	          budget: t.Optional(
116	            t.Object({
117	              max_tasks: t.Optional(t.Number()),
118	              max_retries: t.Optional(t.Number()),
119	              timeout_minutes: t.Optional(t.Number()),
120	            })
121	          ),
122	          concurrency: t.Optional(
123	            t.Object({
124	              max_concurrent: t.Optional(t.Number()),
125	            })
126	          ),
127	          auto_approve: t.Optional(t.Boolean()),
128	          prompt_template: t.Optional(t.String()),
129	        }),
130	      }
131	    )
132	
133	    // AC: @api-contract ac-17 - List workflows
134	    .get('/workflows', async ({ projectContext }) => {
135	      // AC: @multi-directory-daemon ac-1, ac-24 - Use project context from middleware
136	      const ctx = await initContext(projectContext.path);
137	      const meta = await loadMetaContext(ctx);
138	
139	      // AC: @api-contract ac-17 - Return all defined workflows
140	      const workflows = meta.workflows;
141	
142	      return {
143	        items: workflows,
144	        total: workflows.length,
145	      };
146	    })
147	
148	    // AC: @api-contract ac-18 - List observations with filter
149	    .get(
150	      '/observations',
151	      async ({ query, projectContext }) => {
152	        // AC: @multi-directory-daemon ac-1, ac-24 - Use project context from middleware
153	        const ctx = await initContext(projectContext.path);
154	        const meta = await loadMetaContext(ctx);
155	
156	        // Start with all observations
157	        let filtered = meta.observations || [];
158	
159	        // AC: @api-contract ac-18 - Filter by resolved status
160	        if (query.resolved !== undefined) {
161	          const resolvedFilter = query.resolved === 'true';
162	          filtered = filtered.filter((obs) => {
163	            const isResolved = !!obs.resolved_at;
164	            return isResolved === resolvedFilter;
165	          });
166	        }
167	
168	        // Optional type filter (not in ACs but useful)
169	        if (query.type) {
170	          const typeFilters = Array.isArray(query.type) ? query.type : [query.type];
171	          filtered = filtered.filter((obs) => typeFilters.includes(obs.type));
172	        }
173	
174	        // Sort by created_at descending (newest first)
175	        const sorted = [...filtered].sort(
176	          (a, b) => new Date(b.created_at).getTime() - new Date(a.created_at).getTime()
177	        );
178	
179	        return {
180	          items: sorted,
181	          total: sorted.length,
182	        };
183	      },
184	      {
185	        query: t.Object({
186	          resolved: t.Optional(t.String()),
187	          type: t.Optional(t.Union([t.String(), t.Array(t.String())])),
188	        }),
189	      }
190	    );
191	}

