  1	<script lang="ts">
  2		// AC: @ui-agent-dispatch ac-1 — Agent definitions with name, triggers, active/completed counts
  3		// AC: @ui-agent-dispatch ac-2 — Dispatch running: status, stop button, active invocations
  4		// AC: @ui-agent-dispatch ac-3 — Dispatch stopped: status shown, no active invocations
  5		import { onMount, onDestroy } from 'svelte';
  6		import {
  7			fetchAgentStatus,
  8			fetchAgentDefinitions,
  9			controlDispatch,
 10			type AgentDefinition,
 11			type AgentDispatchStatus,
 12			type ActiveInvocation
 13		} from '$lib/api';
 14		import { subscribe, unsubscribe, on, off } from '$lib/stores/connection.svelte';
 15		import { isStaticMode, ReadOnlyModeError } from '$lib/stores/mode.svelte';
 16		import { getProjectVersion } from '$lib/stores/project.svelte';
 17		import AgentCard from '$lib/components/agents/AgentCard.svelte';
 18		import AgentEditForm from '$lib/components/agents/AgentEditForm.svelte';
 19		import DispatchStatusComponent from '$lib/components/agents/DispatchStatus.svelte';
 20		import ActiveInvocationRow from '$lib/components/agents/ActiveInvocationRow.svelte';
 21		import { Separator } from '$lib/components/ui/separator';
 22		import { Skeleton } from '$lib/components/ui/skeleton';
 23		import Bot from '@lucide/svelte/icons/bot';
 24		import Zap from '@lucide/svelte/icons/zap';
 25	
 26		let agentDefinitions = $state<AgentDefinition[]>([]);
 27		let dispatchStatus = $state<AgentDispatchStatus | null>(null);
 28		let loading = $state(true);
 29		let error = $state('');
 30		let isToggling = $state(false);
 31	
 32		// AC: @ui-agent-dispatch ac-4 — Edit form state
 33		let editDialogOpen = $state(false);
 34		let editingAgent = $state<AgentDefinition | null>(null);
 35	
 36		// Screen reader announcement for live invocation updates
 37		let invocationAnnouncement = $state('');
 38	
 39		// Track completed invocations per agent (incremented by WebSocket events)
 40		let completedCounts = $state<Record<string, number>>({});
 41	
 42		// Derive active counts per agent from dispatch status
 43		let activeCounts = $derived.by(() => {
 44			const counts: Record<string, number> = {};
 45			if (dispatchStatus?.active_invocations) {
 46				for (const inv of dispatchStatus.active_invocations) {
 47					counts[inv.agent_id] = (counts[inv.agent_id] || 0) + 1;
 48				}
 49			}
 50			return counts;
 51		});
 52	
 53		// Reload on project change
 54		$effect(() => {
 55			const version = getProjectVersion();
 56			if (version > 0) {
 57				loadData();
 58			}
 59		});
 60	
 61		async function loadData() {
 62			loading = true;
 63			error = '';
 64	
 65			try {
 66				const [statusResult, defsResult] = await Promise.all([
 67					fetchAgentStatus(),
 68					fetchAgentDefinitions()
 69				]);
 70				dispatchStatus = statusResult;
 71				agentDefinitions = defsResult.items;
 72	
 73				// Pre-populate completed counts from API (server-side aggregation from session history)
 74				const initial: Record<string, number> = {};
 75				for (const def of statusResult.agent_definitions) {
 76					if (def.completed_sessions != null && def.completed_sessions > 0) {
 77						initial[def.id] = def.completed_sessions;
 78					}
 79				}
 80				completedCounts = initial;
 81			} catch (err) {
 82				error = err instanceof Error ? err.message : 'Failed to load agent data';
 83				console.error('Error loading agent data:', err);
 84			} finally {
 85				loading = false;
 86			}
 87		}
 88	
 89		async function handleStartDispatch() {
 90			if (isStaticMode()) return;
 91			isToggling = true;
 92			error = '';
 93	
 94			try {
 95				const result = await controlDispatch('start');
 96				// Refresh full status after toggle
 97				dispatchStatus = await fetchAgentStatus();
 98			} catch (err) {
 99				if (err instanceof ReadOnlyModeError) {
100					error = err.message;
101				} else {
102					error = err instanceof Error ? err.message : 'Failed to start dispatch';
103				}
104			} finally {
105				isToggling = false;
106			}
107		}
108	
109		async function handleStopDispatch() {
110			if (isStaticMode()) return;
111			isToggling = true;
112			error = '';
113	
114			try {
115				const result = await controlDispatch('stop');
116				// Refresh full status after toggle
117				dispatchStatus = await fetchAgentStatus();
118			} catch (err) {
119				if (err instanceof ReadOnlyModeError) {
120					error = err.message;
121				} else {
122					error = err instanceof Error ? err.message : 'Failed to stop dispatch';
123				}
124			} finally {
125				isToggling = false;
126			}
127		}
128	
129		function handleAgentEvent(event: any) {
130			if (event.event === 'agent_invocation') {
131				const data = event.data;
132				if (data.status === 'completed' || data.status === 'failed') {
133					completedCounts = {
134						...completedCounts,
135						[data.agent_id]: (completedCounts[data.agent_id] || 0) + 1
136					};
137				}
138				// Announce change to screen readers
139				const agentLabel = data.agent_id || 'Agent';
140				if (data.status === 'started') {
141					invocationAnnouncement = `${agentLabel} invocation started`;
142				} else if (data.status === 'completed') {
143					invocationAnnouncement = `${agentLabel} invocation completed`;
144				} else if (data.status === 'failed') {
145					invocationAnnouncement = `${agentLabel} invocation failed`;
146				}
147				// Refresh status to update active invocations
148				fetchAgentStatus()
149					.then((status) => {
150						dispatchStatus = status;
151					})
152					.catch((err) => console.error('Error refreshing agent status:', err));
153			}
154		}
155	
156		// AC: @ui-agent-dispatch ac-4 — Open edit dialog for an agent
157		function handleEditAgent(agent: AgentDefinition) {
158			editingAgent = agent;
159			editDialogOpen = true;
160		}
161	
162		function handleAgentSaved(updated: AgentDefinition) {
163			// Update the agent in the local list
164			agentDefinitions = agentDefinitions.map((a) =>
165				a.id === updated.id ? updated : a
166			);
167		}
168	
169		onMount(() => {
170			loadData();
171			subscribe(['agents']);
172			on('agents', handleAgentEvent);
173		});
174	
175		onDestroy(() => {
176			off('agents', handleAgentEvent);
177			unsubscribe(['agents']);
178		});
179	</script>
180	
181	<div class="flex flex-col gap-6 p-6">
182		<div>
183			<h1 class="text-3xl font-bold mb-2">Agents</h1>
184			<p class="text-muted-foreground">Agent definitions and dispatch engine status.</p>
185		</div>
186	
187		<!-- Error State -->
188		{#if error}
189			<div
190				class="bg-destructive/10 text-destructive p-4 rounded-lg"
191				data-testid="error-message"
192				role="alert"
193			>
194				{error}
195			</div>
196		{/if}
197	
198		<!-- Loading Skeleton -->
199		{#if loading}
200			<div class="flex flex-col gap-4" data-testid="agents-loading">
201				<Skeleton class="h-16 w-full rounded-lg" />
202				<Separator />
203				<div class="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
204					<Skeleton class="h-40 rounded-lg" />
205					<Skeleton class="h-40 rounded-lg" />
206				</div>
207			</div>
208		{:else}
209			<!-- Dispatch Status Section -->
210			<!-- AC: @ui-agent-dispatch ac-2, ac-3 -->
211			<section data-testid="dispatch-section">
212				<h2 class="text-lg font-semibold mb-3">Dispatch Engine</h2>
213				{#if dispatchStatus}
214					<DispatchStatusComponent
215						enabled={dispatchStatus.dispatch_enabled}
216						activeCount={dispatchStatus.active_invocations.length}
217						queueDepth={dispatchStatus.queue_depth}
218						onStart={handleStartDispatch}
219						onStop={handleStopDispatch}
220						{isToggling}
221					/>
222				{/if}
223			</section>
224	
225			<!-- Active Invocations Section -->
226			<!-- AC: @ui-agent-dispatch ac-2 -->
227			{#if dispatchStatus?.dispatch_enabled}
228				<section data-testid="active-invocations-section" aria-live="polite" aria-relevant="additions removals">
229					<h2 class="text-lg font-semibold mb-3">Active Invocations</h2>
230					{#if dispatchStatus.active_invocations.length > 0}
231						<div class="flex flex-col gap-2">
232							{#each dispatchStatus.active_invocations as invocation (invocation.session_id)}
233								<ActiveInvocationRow {invocation} />
234							{/each}
235						</div>
236					{:else}
237						<div
238							class="flex flex-col items-center justify-center py-8 text-center border rounded-lg"
239							data-testid="active-invocations-empty"
240						>
241							<Zap class="h-10 w-10 text-muted-foreground mb-3" />
242							<h3 class="text-sm font-medium mb-1">No active invocations</h3>
243							<p class="text-xs text-muted-foreground max-w-sm">
244								Dispatch is running and waiting for eligible tasks. Use
245								<code class="bg-muted px-1 py-0.5 rounded">kspec tasks ready --eligible</code>
246								to check for work.
247							</p>
248						</div>
249					{/if}
250				</section>
251			{/if}
252	
253			<!-- Screen reader live announcement for invocation changes -->
254			<div class="sr-only" aria-live="assertive" aria-atomic="true" data-testid="invocation-live-region">
255				{invocationAnnouncement}
256			</div>
257	
258			<Separator />
259	
260			<!-- Agent Definitions Section -->
261			<!-- AC: @ui-agent-dispatch ac-1 -->
262			<section data-testid="agent-definitions-section">
263				<h2 class="text-lg font-semibold mb-3">
264					Agent Definitions
265					{#if agentDefinitions.length > 0}
266						<span class="text-sm font-normal text-muted-foreground">({agentDefinitions.length})</span>
267					{/if}
268				</h2>
269	
270				{#if agentDefinitions.length === 0}
271					<!-- Empty State -->
272					<div
273						class="flex flex-col items-center justify-center py-12 text-center border rounded-lg"
274						data-testid="agents-empty-state"
275					>
276						<Bot class="h-12 w-12 text-muted-foreground mb-4" />
277						<h3 class="text-lg font-medium mb-1">No agents defined</h3>
278						<p class="text-sm text-muted-foreground max-w-sm">
279							Agent definitions are configured in kynetic.meta.yaml. Use
280							<code class="text-xs bg-muted px-1 py-0.5 rounded">kspec setup</code>
281							to create default agent definitions.
282						</p>
283					</div>
284				{:else}
285					<div class="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
286						{#each agentDefinitions as agent (agent.id)}
287							<AgentCard
288								{agent}
289								activeCount={activeCounts[agent.id] || 0}
290								completedCount={completedCounts[agent.id] || 0}
291								onEdit={() => handleEditAgent(agent)}
292							/>
293						{/each}
294					</div>
295				{/if}
296			</section>
297		{/if}
298	
299		<!-- AC: @ui-agent-dispatch ac-4 — Agent edit dialog -->
300		{#if editingAgent}
301			<AgentEditForm
302				bind:open={editDialogOpen}
303				agent={editingAgent}
304				onSaved={handleAgentSaved}
305			/>
306		{/if}
307	</div>

